use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::io::{self, BufRead, Write};

#[derive(Debug, Deserialize, Serialize)]
struct Finding {
    host: String,
    finding: String,
    severity: String,
}

fn main() {
    let mut findings = HashMap::new();
    let mut line_number = 0;

    let stdin = io::stdin();
    let mut reader = stdin.lock();

    loop {
        line_number += 1;
        let mut line = String::new();
        match reader.read_line(&mut line) {
            Ok(0) => break,
            Ok(_) => {
                let finding: Finding = match serde_json::from_str(&line) {
                    Ok(finding) => finding,
                    Err(err) => {
                        eprintln!("Line {}: {}", line_number, err);
                        continue;
                    }
                };

                if !["low", "medium", "high", "critical"].contains(&finding.severity.as_str()) {
                    eprintln!("Line {}: Invalid severity: {}", line_number, finding.severity);
                    continue;
                }

                let key = (finding.host, finding.finding, finding.severity);
                if findings.contains_key(&key) {
                    continue;
                }

                findings.insert(key, finding);
            }
            Err(err) => {
                eprintln!("Error reading line {}: {}", line_number, err);
                std::process::exit(1);
            }
        }
    }

    let mut findings_vec: Vec<_> = findings.into_values().collect();
    findings_vec.sort_by(|a, b| {
        let severity_cmp = b.severity.cmp(&a.severity);
        if severity_cmp != std::cmp::Ordering::Equal {
            return severity_cmp;
        }
        let host_cmp = a.host.cmp(&b.host);
        if host_cmp != std::cmp::Ordering::Equal {
            return host_cmp;
        }
        a.finding.cmp(&b.finding)
    });

    let mut counts = HashMap::new();
    for finding in &findings_vec {
        *counts.entry(&finding.severity).or_insert(0) += 1;
    }

    let mut writer = io::stdout();
    for finding in findings_vec {
        writeln!(writer, "{}", serde_json::to_string(&finding).unwrap()).unwrap();
    }

    writeln!(writer, "Critical: {}", counts.get("critical").unwrap_or(&0)).unwrap();
    writeln!(writer, "High: {}", counts.get("high").unwrap_or(&0)).unwrap();
    writeln!(writer, "Medium: {}", counts.get("medium").unwrap_or(&0)).unwrap();
    writeln!(writer, "Low: {}", counts.get("low").unwrap_or(&0)).unwrap();
}
