import json
import sys

def validate_json(json_data):
    try:
        data = json.loads(json_data)
        if not isinstance(data, list):
            raise ValueError("Invalid JSON format")
        return data
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON format")

def process_records(records):
    findings = {}
    valid_count = 0
    invalid_count = 0
    truncated_count = 0

    for record in records:
        if not isinstance(record, dict) or 'url' not in record or 'status' not in record or 'headers' not in record:
            invalid_count += 1
            continue

        url = record['url']
        status = record['status']
        headers = record['headers']

        if not isinstance(headers, dict):
            invalid_count += 1
            continue

        if status != 200:
            invalid_count += 1
            continue

        if len(headers) > 10000:
            truncated_count += 1
            continue

        valid_count += 1

        for header_name, header_value in headers.items():
            if not isinstance(header_name, str) or not isinstance(header_value, str):
                invalid_count += 1
                continue

            header_name = header_name.lower()

            if header_name not in findings:
                findings[header_name] = []

            if header_name not in ['strict-transport-security', 'content-security-policy', 'x-content-type-options', 'referrer-policy']:
                invalid_count += 1
                continue

            findings[header_name].append(url)

    return findings, valid_count, invalid_count, truncated_count

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <json_file_path>")
        sys.exit(1)

    json_file_path = sys.argv[1]

    try:
        with open(json_file_path, 'r', encoding='utf-8') as file:
            json_data = file.read()
            records = validate_json(json_data)
            findings, valid_count, invalid_count, truncated_count = process_records(records)

            output = {
                'findings': findings,
                'valid_count': valid_count,
                'invalid_count': invalid_count,
                'truncated_count': truncated_count
            }

            print(json.dumps(output, indent=4))
    except FileNotFoundError:
        print(f"File not found: {json_file_path}")
    except ValueError as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
