int parse_record(const uint8_t *buf, size_t len, struct record *out) {
    if (buf == NULL || out == NULL || len < 3) {
        return -1;
    }

    size_t payload_len = (buf[0] << 8) | buf[1];
    if (payload_len > 4096 || payload_len + 3 > len) {
        return -2;
    }

    out->type = buf[2];
    out->payload = buf + 3;
    out->payload_len = payload_len;

    return 0;
}

