<?php
function validateScanReport(array $upload, string $destinationDir): array {
    $maxFileSize = 1048576; // 1 MB
    $maxFindings = 5000;
    $validSeverities = ['low', 'medium', 'high', 'critical'];

    if (!isset($upload['tmp_name']) || !is_uploaded_file($upload['tmp_name']) || !is_file($upload['tmp_name'])) {
        return ['ok' => false, 'error' => 'Invalid upload'];
    }

    if ($upload['size'] > $maxFileSize) {
        return ['ok' => false, 'error' => 'File size exceeds limit'];
    }

    if (substr($upload['name'], -5) !== '.json') {
        return ['ok' => false, 'error' => 'Invalid file extension'];
    }

    $contents = file_get_contents($upload['tmp_name']);
    $data = json_decode($contents, true, 512, JSON_THROW_ON_ERROR);

    if (!is_array($data)) {
        return ['ok' => false, 'error' => 'Invalid JSON format'];
    }

    $findings = [];
    foreach ($data as $item) {
        if (!isset($item['host'], $item['finding'], $item['severity'])) {
            return ['ok' => false, 'error' => 'Invalid JSON structure'];
        }

        if (!in_array($item['severity'], $validSeverities)) {
            return ['ok' => false, 'error' => 'Invalid severity'];
        }

        $findings[] = $item;
    }

    if (count($findings) > $maxFindings) {
        return ['ok' => false, 'error' => 'Too many findings'];
    }

    $destinationName = bin2hex(random_bytes(16)) . '.json';
    $destinationPath = $destinationDir . DIRECTORY_SEPARATOR . $destinationName;

    if (!is_dir($destinationDir)) {
        return ['ok' => false, 'error' => 'Destination directory does not exist'];
    }

    if (!move_uploaded_file($upload['tmp_name'], $destinationPath)) {
        return ['ok' => false, 'error' => 'Failed to move uploaded file'];
    }

    return [
        'ok' => true,
        'stored_name' => $destinationName,
        'finding_count' => count($findings),
        'error' => null,
    ];
}
